import sys

def solve_case(n, a):
    if len(set(a)) == 1:
        return 0, []

    target = sum(a) // n
    operations = []

    for i in range(n):
        diff = a[i] - target
        if diff > 0:
            for j in range(n):
                if j != i:
                    x = min(diff, a[j])
                    a[i] -= x
                    a[j] += x
                    operations.append((i + 1, j + 1, x))
                    if a[i] == target:
                        break

    if all(x == target for x in a):
        return len(operations), operations
    else:
        return -1, []

